import tree_sitter_python as tspython
from tree_sitter import Language, Parser

parser = Parser(Language(tspython.language()))
src = open("billing.py", "rb").read()
tree = parser.parse(src)

def find_function(node, name):
    if node.type == "function_definition":
        if node.child_by_field_name("name").text.decode() == name:
            return node
    for child in node.children:
        if (hit := find_function(child, name)):
            return hit

fn = find_function(tree.root_node, "apply_tax")
print(fn.start_point[0] + 1, fn.end_point[0] + 1)   # line range, e.g. 42 57
snippet = src[fn.start_byte:fn.end_byte].decode()   # only this goes to the LLM
